"""Decoder for the internal ``trk`` telemetry format.

Each record has a one-byte type, a little-endian uint16 payload length,
then the payload and a little-endian CRC-32 (seed 0x9c2f41b7) covering
both header and payload. Payload integers are big-endian.
"""

from datetime import datetime, timedelta, timezone
import zlib


_CRC_SEED = 0x9C2F41B7
_EPOCH = datetime(2000, 1, 2, tzinfo=timezone.utc)
_FLAG_NAMES = ("low_battery", "recal", "stale")


def decode_records(data: bytes) -> list[dict]:
    """Decode samples and batches, rejecting damaged or incomplete records.

    Samples (type 2) contain uint32 minutes since the device epoch, a
    uint24 value in thousandths, and a flag byte. Batches (type 7) contain
    a uint16 count, that many uint16 values in hundredths, and a flag byte.
    """
    records = []
    offset = 0
    while offset < len(data):
        if len(data) - offset < 3:
            raise ValueError("truncated record header")
        kind = data[offset]
        size = int.from_bytes(data[offset + 1:offset + 3], "little")
        payload_end = offset + 3 + size
        end = payload_end + 4
        if end > len(data):
            raise ValueError("truncated record payload or checksum")
        expected_crc = int.from_bytes(data[payload_end:end], "little")
        if zlib.crc32(data[offset:payload_end], _CRC_SEED) != expected_crc:
            raise ValueError(f"checksum mismatch at offset {offset}")
        payload = data[offset + 3:payload_end]
        if kind == 2:
            if size != 8:
                raise ValueError("invalid sample payload length")
            minutes = int.from_bytes(payload[:4], "big")
            timestamp = _EPOCH + timedelta(minutes=minutes)
            record = {
                "type": "sample",
                "ts": timestamp.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "value": int.from_bytes(payload[4:7], "big") / 1000,
            }
        elif kind == 7:
            if size < 3:
                raise ValueError("invalid batch payload length")
            count = int.from_bytes(payload[:2], "big")
            if size != 2 * count + 3:
                raise ValueError("invalid batch payload length")
            record = {
                "type": "batch",
                "values": [
                    int.from_bytes(payload[i:i + 2], "big") / 100
                    for i in range(2, 2 + 2 * count, 2)
                ],
            }
        else:
            raise ValueError(f"unknown record type: {kind}")
        record["flags"] = [
            name for bit, name in enumerate(_FLAG_NAMES)
            if payload[-1] & (1 << bit)
        ]
        records.append(record)
        offset = end
    return records
PY
